+export function displaySafeOpenAiSnapshotData<T>(data: T | null): T | null {
+	if (Array.isArray(data)) {
+		return data.map((value) => displaySafeOpenAiSnapshotData(value)) as T;
+	}
+	if (!isStructuredObject(data)) return data;
