   180	export async function storeMcpAppResultSnapshot(args: {
   181		ctx: ToolContext;
   182		toolCallId: unknown;
   183		bindingCapability?: unknown;
   184		toolName: string;
   185		data: UnknownRecord;
   186	}): Promise<boolean> {
   187		const identity = snapshotIdentity(args.ctx, args.toolCallId);
   188		if (
   189			!identity ||
   190			!args.toolName ||
   191			args.toolName.length > TOOL_NAME_MAX_LENGTH
   192		)
   193			return false;
   194		const bindingCapability = normalizeMcpAppToolCallId(args.bindingCapability);
   195		const data = displaySafeMcpAppResult(args.data);
   196		if (!isRecord(data)) return false;
   197		const serialized = serializeSnapshot({
   198			version: 1,
   199			toolName: args.toolName,
   200			data,
   201			viewState: {},
   202			...(bindingCapability
   203				? { bindingKey: hashIdentity(bindingCapability) }
   204				: {}),
   205		});
   206		if (!serialized) return false;
   207	
   208		const sql = getDb();
   209		const collided = await sql.begin(async (tx) => {
   210			const [stored] = await tx<{ collided: boolean }>`
   211				INSERT INTO public.mcp_app_result_snapshots (
   212					organization_id, client_id, user_id, conversation_key,
   213					tool_call_key, tool_name, body, plaintext_bytes, expires_at
   214				) VALUES (
   215					${identity.organizationId}, ${identity.clientId}, ${identity.userId},
   216					${identity.conversationKey}, ${identity.toolCallKey}, ${args.toolName},
   217					${serialized.body}, ${serialized.plaintextBytes},
   218					now() + (${MCP_APP_RESULT_RETENTION_DAYS} * interval '1 day')
   219				)
   220				ON CONFLICT (
   221					organization_id, client_id, user_id, conversation_key, tool_call_key
   222				) DO UPDATE SET
   223					-- A host request ID is not guaranteed to be unique forever. Never let a
   224					-- collision replace the historical card with a different result.
   225					expires_at = now(),
   226					updated_at = now()
   227				RETURNING expires_at <= now() AS collided
   228			`;
   229			await tx`
   230				DELETE FROM public.mcp_app_result_snapshots snapshot
   231				WHERE snapshot.organization_id = ${identity.organizationId}
   232					AND snapshot.client_id = ${identity.clientId}
   233					AND snapshot.user_id = ${identity.userId}
   234					AND snapshot.conversation_key = ${identity.conversationKey}
   235					AND snapshot.tool_call_key NOT IN (
   236						SELECT kept.tool_call_key
   237						FROM public.mcp_app_result_snapshots kept
   238						WHERE kept.organization_id = ${identity.organizationId}
   239							AND kept.client_id = ${identity.clientId}
   240							AND kept.user_id = ${identity.userId}
   241							AND kept.conversation_key = ${identity.conversationKey}
   242						ORDER BY kept.updated_at DESC, kept.tool_call_key
   243						LIMIT ${MCP_APP_RESULT_CONVERSATION_CAP}
   244					)
   245			`;
   246			return stored?.collided === true;
   247		});
   248		if (collided) {
   249			logger.warn(
   250				{ toolName: args.toolName },
   251				"MCP App result snapshot key collision; historical restore disabled",
   252			);
   253		}
   254		return !collided;
   255	}
