	listeners: new Map<string, Set<(params: unknown) => void>>(),
}));

vi.mock("@modelcontextprotocol/ext-apps", () => ({
	App: class {
		addEventListener(name: string, handler: (params: unknown) => void) {
			const handlers = bridge.listeners.get(name) ?? new Set();
			handlers.add(handler);
			bridge.listeners.set(name, handlers);
		}
		removeEventListener(name: string, handler: (params: unknown) => void) {
			bridge.listeners.get(name)?.delete(handler);
		}
		callServerTool = bridge.callServerTool;
		connect = bridge.connect;
		getHostContext() {
			return { theme: "light", ...bridge.hostContext };
		}
		async openLink() {
			return { isError: false };
		}
	},
	PostMessageTransport: class {
		async close() {}
	},
}));

const originalParentDescriptor = Object.getOwnPropertyDescriptor(window, "parent");

describe("review probe", () => {
	beforeEach(() => {
		vi.resetModules();
		vi.clearAllMocks();
		bridge.listeners.clear();
		bridge.hostContext = {};
		bridge.connect.mockResolvedValue(undefined);
	});

	afterEach(() => {
		if (originalParentDescriptor) {
			Object.defineProperty(window, "parent", originalParentDescriptor);
		}
	});

	it("does not bind stale split capability state to later live data", async () => {
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: Object.assign(new EventTarget(), {
				location: { origin: "https://portable-host.example" },
			}),
		});
		type RestoreResult = {
			isError: false;
			structuredContent: {
				found: true;
				tool_name: string;
				data: { title: string };
				view_state: { "details.open": true };
			};
		};
		let resolveRestore!: (result: RestoreResult) => void;
		const restore = new Promise<RestoreResult>((resolve) => {
			resolveRestore = resolve;
		});
		bridge.callServerTool.mockImplementation(async ({ name }) => {
			if (name === "restore_lobu_app_result") return restore;
			if (name === "save_lobu_app_state") {
				return { isError: false, structuredContent: { saved: true } };
			}
			return { isError: false };
		});

		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data, viewState } = useMcpApp<{ title: string }>();
			return (
				<>
					<span>{data?.title ?? "No result"}</span>
					<span>open:{String(viewState["details.open"])}</span>
				</>
			);
		}
		render(
			<Provider devMock={{ title: "Development result" }}>
				<Probe />
			</Provider>,
		);
		await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));

		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? []) {
				handler({ structuredContent: { title: "First unkeyed card" } });
			}
		});
		expect(await screen.findByText("First unkeyed card")).toBeInTheDocument();

		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? []) {
				handler({
					structuredContent: {},
					_meta: { "lobu/mcp-app-snapshot-capability": "stale-token" },
				});
			}
		});
		await waitFor(() =>
			expect(bridge.callServerTool).toHaveBeenCalledWith({
				name: "restore_lobu_app_result",
				arguments: { snapshot_capability: "stale-token" },
			}),
		);

		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? []) {
				handler({ structuredContent: { title: "Current unkeyed card" } });
			}
		});
		expect(await screen.findByText("Current unkeyed card")).toBeInTheDocument();

		await act(async () => {
			resolveRestore({
				isError: false,
				structuredContent: {
					found: true,
					tool_name: "query_sdk",
					data: { title: "Stale capability card" },
					view_state: { "details.open": true },
				},
			});
			await restore;
		});

		expect(screen.getByText("Current unkeyed card")).toBeInTheDocument();
		expect(await screen.findByText("open:undefined")).toBeInTheDocument();
	});
});

